package com.neighbormarket.service;
import com.baomidou.mybatisplus.core.metadata.IPage; import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.neighbormarket.domain.*; import com.neighbormarket.mapper.*; import com.neighbormarket.web.ItemController.CreateItemRequest; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.time.LocalDateTime;
@Service public class ItemService {
 public static final String PLACEHOLDER_IMAGE="https://placehold.co/800x600/F4EBDD/37534A?text=NeighborMarket",DISPLAY_TIME_ZONE="Asia/Shanghai"; private final ItemMapper items; private final AppUserMapper users; private final ExchangeService exchange;
 @org.springframework.beans.factory.annotation.Autowired public ItemService(ItemMapper a,AppUserMapper b,ExchangeService e){items=a;users=b;exchange=e;} public ItemService(ItemMapper a,AppUserMapper b){this(a,b,null);}
 public IPage<ItemView> market(Page<Item> page,String keyword,String category,TradeType tradeType,ItemStatus status){ItemStatus target=status==null?ItemStatus.AVAILABLE:status;var q=Wrappers.lambdaQuery(Item.class).eq(Item::getStatus,target);if(keyword!=null&&!keyword.isBlank()){String t=keyword.trim();q.and(x->x.like(Item::getTitle,t).or().like(Item::getDescription,t));}if(category!=null&&!category.isBlank())q.eq(Item::getCategory,category.trim());if(tradeType!=null)q.eq(Item::getTradeType,tradeType);q.orderByDesc(Item::getPublishedAt).orderByDesc(Item::getId);return items.selectPage(page,q).convert(this::view);}
 public ItemView detail(Long id){Item i=items.selectById(id);if(i==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"物品不存在");return view(i);}
 @Transactional public ItemView create(CreateItemRequest r,String username){AppUser p=findUser(username);BigDecimal price=normalizePrice(r.tradeType(),r.price());LocalDateTime now=LocalDateTime.now();Item i=new Item();i.setPublisherId(p.getId());i.setTitle(r.title().trim());i.setDescription(r.description().trim());i.setCategory(r.category().trim());i.setTradeType(r.tradeType());i.setPrice(price);i.setImageUrl(PLACEHOLDER_IMAGE);i.setStatus(ItemStatus.AVAILABLE);i.setPublishedAt(now);i.setLastConfirmedAt(now);i.setPickupLocation(r.pickupLocation().trim());items.insert(i);exchange.addInitialSlots(i,r.slots());return view(i);}
 public IPage<ItemView> mine(Page<Item> p,String username){AppUser u=findUser(username);return items.selectPage(p,Wrappers.lambdaQuery(Item.class).eq(Item::getPublisherId,u.getId()).orderByDesc(Item::getPublishedAt).orderByDesc(Item::getId)).convert(this::view);}
 @Transactional public ItemView confirmAvailable(Long id,String username){AppUser u=findUser(username);Item i=items.selectById(id);if(i==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"物品不存在");if(!i.getPublisherId().equals(u.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"只有发布者可以确认物品状态");if(i.getStatus()!=ItemStatus.AVAILABLE)throw new ResponseStatusException(HttpStatus.CONFLICT,"只有可领取物品可以确认还在");LocalDateTime now=LocalDateTime.now();int n=items.update(null,Wrappers.lambdaUpdate(Item.class).eq(Item::getId,id).eq(Item::getPublisherId,u.getId()).eq(Item::getStatus,ItemStatus.AVAILABLE).set(Item::getLastConfirmedAt,now));if(n!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"物品状态已变化，请刷新后重试");return view(items.selectById(id));}
 static BigDecimal normalizePrice(TradeType t,BigDecimal p){if(t==TradeType.FIXED_PRICE){if(p==null||p.compareTo(BigDecimal.ZERO)<=0)throw new IllegalArgumentException("标价必须大于0元");return p;}if(p!=null)throw new IllegalArgumentException(t==TradeType.FREE?"免费送无需填写价格":"随便给无需填写价格");return t==TradeType.FREE?BigDecimal.ZERO:null;}
 private AppUser findUser(String n){return users.selectOne(Wrappers.lambdaQuery(AppUser.class).eq(AppUser::getUsername,n));}
 private ItemView view(Item i){AppUser p=users.selectById(i.getPublisherId());LocalDateTime now=LocalDateTime.now();return new ItemView(i.getId(),i.getTitle(),i.getDescription(),i.getCategory(),i.getTradeType(),i.getPrice(),i.getImageUrl(),i.getStatus(),i.getPublishedAt(),i.getLastConfirmedAt(),i.getCompletedAt(),i.getPickupLocation(),i.getCurrentHandoverId(),FreshnessRules.label(i.getPublishedAt(),now),FreshnessRules.isConfirmationStale(i.getLastConfirmedAt(),now),DISPLAY_TIME_ZONE,new PublisherView(p.getId(),p.getNickname()));}
 public record PublisherView(Long id,String nickname){} public record ItemView(Long id,String title,String description,String category,TradeType tradeType,BigDecimal price,String imageUrl,ItemStatus status,LocalDateTime publishedAt,LocalDateTime lastConfirmedAt,LocalDateTime completedAt,String pickupLocation,Long currentHandoverId,String freshnessLabel,boolean confirmationStale,String displayTimeZone,PublisherView publisher){}
}